public static TFMTranslationLabelIdLookupTable Find(LabelString _labelString, boolean _select4Update = false)
{
    TFMTranslationLabelIdLookupTable translation;

    translation.selectForUpdate(_select4Update);

    select firstonly translation where translation.LabelString == _labelString;

    if (!translation)
    {
        translation.LabelId = _labelString;
        translation.LabelString = _labelString;
    }

    return translation;
}

public static boolean checkExisting(LabelString _labelString)
{
    TFMTranslationLabelIdLookupTable translation;

    translation.selectForUpdate(false);

    select firstonly translation where translation.LabelString == _labelString;

    return translation && translation.RecId;
}

public static void create(LabelString _labelString, LabelId _labelID)
{
    TFMTranslationLabelIdLookupTable translation;

    translation.LabelString = _labelString;

    translation.LabelId = _labelID;
    translation.insert();
}

public display LabelString LabelTranslated()
{
    return SysLabel::isLabelId(this.LabelID) ? SysLabel::labelId2String(this.LabelID,new xInfo().language()) : this.LabelID;
}

/// <summary>
/// Returns how many entries there are for a given LabelFile.
/// </summary>
/// <returns>an Integer of how many entries there are for a given LabelFile.</returns>
public display Integer CountTotal()
{
    TFMTranslationLabelIdLookupTable lookuptable;

    select count(RecId) from lookuptable
        where lookuptable.LabelFile == this.LabelFile;

    return lookuptable.RecId;
}

/// <summary>
/// Deletes all entries with the provided _labelFildId
/// </summary>
public static void deleteLookupEntries(str _labelFileId)
{
    TFMTranslationLabelIdLookupTable translationLookup;
    delete_from translationLookup where translationLookup.LabelFile == _labelFileId;
}
